import{_ as t,o as s,c as a,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"Dépannage","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Dépannage","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/referent/depannage.md","filePath":"documentation/referent/depannage.md"}'),r={name:"documentation/referent/depannage.md"};function n(d,e,i,c,u,l){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="dépannage" tabindex="-1">Dépannage <a class="header-anchor" href="#dépannage" aria-label="Permalink to &quot;Dépannage {#dépannage}&quot;">​</a></h1><p><strong>Avant tout : <code>sudo teuthis diagnostic</code>.</strong> Il écrit un fichier texte (<code>/opt/teuthis/journaux/diagnostic-AAAAMMJJ-HHMMSS.txt</code>, droits 600) qui rassemble l&#39;état de la pile : système, Docker, services et leur santé, dernières lignes de journal de chaque service, <code>.env</code> <strong>sans aucun secret</strong> (seuls les noms de domaine, la version, le profil, les profils Compose et quelques réglages sans danger sont en clair ; mots de passe, clés, jetons et courriels sont masqués), gabarits Caddy actifs, résolution DNS, ports en écoute, échéance des certificats, dernier échec de sauvegarde. C&#39;est ce fichier — relu avant de le partager — qu&#39;on joint à une demande d&#39;aide. <code>sudo teuthis etat</code> donne en quelques lignes la version, les services et la dernière sauvegarde.</p><table tabindex="0"><thead><tr><th>Symptôme</th><th>Où lire</th></tr></thead><tbody><tr><td>Le site ne s&#39;ouvre pas, le navigateur refuse le certificat</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#site-inaccessible-ou-certificat-refusé">Site inaccessible ou certificat refusé</a></td></tr><tr><td>Page « 502 Bad Gateway »</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#502-de-caddy">502 de Caddy</a></td></tr><tr><td>Un service est <code>unhealthy</code> ou ne cesse de redémarrer</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#un-service-est-unhealthy">Un service est unhealthy</a></td></tr><tr><td>La base ne démarre pas</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#la-base-ne-démarre-pas">La base ne démarre pas</a></td></tr><tr><td>Plus de place sur le disque</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#disque-plein">Disque plein</a></td></tr><tr><td>Le service <code>sauvegarde</code> est <code>unhealthy</code></td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#la-sauvegarde-est-unhealthy">La sauvegarde est unhealthy</a></td></tr><tr><td><code>teuthis mettre-a-jour</code> a échoué</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#une-mise-à-jour-a-échoué">Une mise à jour a échoué</a></td></tr><tr><td>Aucun courriel ne part</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#les-courriels-ne-partent-pas">Les courriels ne partent pas</a></td></tr><tr><td>Tous les formulaires publics sont refusés</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#le-captcha-refuse-tout">Le captcha refuse tout</a></td></tr><tr><td>Certificats, jetons ou captcha bizarres, dates fausses</td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#lhorloge-du-serveur">L&#39;horloge du serveur</a></td></tr></tbody></table><h2 id="site-inaccessible-ou-certificat-refusé" tabindex="-1">Site inaccessible ou certificat refusé <a class="header-anchor" href="#site-inaccessible-ou-certificat-refusé" aria-label="Permalink to &quot;Site inaccessible ou certificat refusé {#site-inaccessible-ou-certificat-refusé}&quot;">​</a></h2><p><strong>Cause la plus fréquente : Let&#39;s Encrypt n&#39;a pas pu joindre le serveur</strong> pour émettre le certificat. Dans l&#39;ordre :</p><ol><li><strong>Le DNS.</strong> Chaque nom (<code>cms.</code>, <code>www.</code>, <code>api.</code>) doit se résoudre vers une adresse de ce serveur (enregistrement A, et AAAA seulement si le serveur a de l&#39;IPv6 — un AAAA erroné suffit à faire échouer Let&#39;s Encrypt). <code>getent ahosts cms.ville.fr</code> donne ce que voit le serveur ; <code>hostname -I</code> donne ses adresses. Derrière une adresse « flottante » ou un NAT de l&#39;hébergeur, l&#39;adresse publique n&#39;apparaît pas sur le serveur : vérifiez-la dans l&#39;interface de l&#39;hébergeur. Le diagnostic compare les deux.</li><li><strong>Les ports 80 et 443</strong> doivent être ouverts de l&#39;extérieur : pare-feu du serveur (<code>sudo ufw status</code>) <strong>et</strong> pare-feu de l&#39;hébergeur. Let&#39;s Encrypt vérifie sur ces deux ports, et aucun autre. <code>ss -ltnp | grep -E &#39;:(80|443) &#39;</code> montre ce qui écoute localement (Caddy, via Docker).</li><li><strong>Ce que Caddy en dit</strong> : <code>cd /opt/teuthis &amp;&amp; docker compose logs --tail 100 caddy</code>. Une erreur « 403 », « Timeout during connect » ou « no valid A records » désigne le DNS ou les ports ; « too many certificates » ou « rate limit » désigne la limite de taux de Let&#39;s Encrypt.</li><li><strong>La limite de taux de Let&#39;s Encrypt</strong> (quelques échecs par heure et par nom, et un plafond de certificats par semaine et par domaine) se déclenche après des essais répétés. Attendez (le message de Caddy donne l&#39;heure de reprise), ou <strong>répétez sans épuiser la limite</strong> avec l&#39;environnement de test : <code>TEUTHIS_TLS=essai</code> dans le <code>.env</code>, puis <code>docker compose up -d</code> (le certificat de test n&#39;est reconnu par aucun navigateur) ; remettez <code>production</code> quand tout est en place. Caddy réessaie tout seul, sans rien à relancer.</li><li>Une fois la cause corrigée : <code>docker compose restart caddy</code>, puis <code>curl -I https://cms.ville.fr</code>.</li></ol><p>Un certificat qui expire bientôt est signalé par <code>sudo teuthis diagnostic</code> (section Certificats) ; Caddy le renouvelle seul tant que les ports 80 et 443 restent joignables.</p><h2 id="502-de-caddy" tabindex="-1">502 de Caddy <a class="header-anchor" href="#502-de-caddy" aria-label="Permalink to &quot;502 de Caddy {#502-de-caddy}&quot;">​</a></h2><p>Caddy répond, mais <strong>le service derrière lui ne répond pas</strong>. <code>docker compose ps</code> dit lequel : <code>cms-admin</code> pour <code>cms.</code>, <code>cms-front</code> pour <code>www.</code>, <code>cms-api</code> pour les routes <code>/_api/</code>.</p><ul><li><strong>Quelques secondes après un démarrage ou une mise à jour</strong> : normal, le temps que le service devienne sain.</li><li><strong><code>cms-front</code> absent</strong> : le gabarit <code>www.caddy</code> est actif mais le profil Compose <code>front</code> ne l&#39;est pas. Vérifiez <code>COMPOSE_PROFILES=front</code> dans le <code>.env</code> (une option <code>--profile</code> en ligne de commande <strong>remplace</strong> cette liste : voir <a href="/teuthis-cms-distribution/documentation/referent/activer-un-module-facultatif#activer-un-module-facultatif">Activer un module facultatif</a>), puis <code>docker compose up -d</code>.</li><li><strong>Service arrêté ou en boucle de redémarrage</strong> : <code>docker compose logs --tail 100 &lt;service&gt;</code> (voir aussi le paragraphe suivant).</li></ul><h2 id="un-service-est-unhealthy" tabindex="-1">Un service est unhealthy <a class="header-anchor" href="#un-service-est-unhealthy" aria-label="Permalink to &quot;Un service est unhealthy {#un-service-est-unhealthy}&quot;">​</a></h2><p><code>docker compose ps</code> (ou <code>sudo teuthis etat</code>) montre l&#39;état de chaque service ; <code>unhealthy</code> veut dire que sa sonde de santé échoue. <strong>Lisez le journal de ce service-là</strong> : <code>docker compose logs --tail 100 &lt;service&gt;</code>, et le détail de la sonde (rubrique <code>State</code>, puis <code>Health</code>, avec les dernières réponses) : <code>docker inspect $(docker compose ps -q &lt;service&gt;)</code>.</p><table tabindex="0"><thead><tr><th>Service</th><th>Ce qu&#39;il faut lire</th></tr></thead><tbody><tr><td><code>cms-api</code></td><td>Un réglage illisible l&#39;empêche de démarrer (message du journal : quelle variable) ; ou la base est injoignable (<a href="/teuthis-cms-distribution/documentation/referent/depannage#la-base-ne-démarre-pas">La base ne démarre pas</a>).</td></tr><tr><td><code>cms-scheduler</code></td><td><code>unhealthy</code> si aucune passe n&#39;a abouti depuis 15 minutes : base injoignable ou boucle figée ; <code>docker compose logs cms-scheduler</code>.</td></tr><tr><td><code>cms-admin</code>, <code>cms-front</code></td><td>Ils attendent <code>cms-api</code> : si elle est malade, commencez par elle.</td></tr><tr><td><code>postgres</code></td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#la-base-ne-démarre-pas">La base ne démarre pas</a>.</td></tr><tr><td><code>sauvegarde</code></td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#la-sauvegarde-est-unhealthy">La sauvegarde est unhealthy</a>.</td></tr><tr><td><code>caddy</code></td><td><a href="/teuthis-cms-distribution/documentation/referent/depannage#site-inaccessible-ou-certificat-refusé">Site inaccessible ou certificat refusé</a>.</td></tr></tbody></table><p>Un service tué faute de mémoire se reconnaît à <code>&quot;OOMKilled&quot;: true</code> dans <code>docker inspect $(docker compose ps -aq &lt;service&gt;)</code> : chaque service a un plafond (<code>TEUTHIS_MEMOIRE_*</code>, voir <code>.env.exemple</code>) et un serveur de 2 Go n&#39;a pas la place d&#39;un module facultatif de plus. Après avoir corrigé le <code>.env</code> : <code>docker compose up -d</code>.</p><h2 id="la-base-ne-démarre-pas" tabindex="-1">La base ne démarre pas <a class="header-anchor" href="#la-base-ne-démarre-pas" aria-label="Permalink to &quot;La base ne démarre pas {#la-base-ne-démarre-pas}&quot;">​</a></h2><p><code>docker compose logs --tail 100 postgres</code> dit pourquoi. Les causes fréquentes :</p><ul><li><strong>Le disque est plein</strong> (« No space left on device ») : voir <a href="/teuthis-cms-distribution/documentation/referent/depannage#disque-plein">Disque plein</a>.</li><li><strong><code>POSTGRES_PASSWORD</code> a été changé après le premier démarrage.</strong> PostgreSQL garde dans son volume le mot de passe de l&#39;initialisation : l&#39;API, avec le nouveau, échoue (« password authentication failed »). Remettez l&#39;ancienne valeur dans le <code>.env</code> (elle figure dans la sauvegarde la plus récente : <code>pile.tar.gz</code>). <strong>Ne le changez jamais</strong> après l&#39;installation.</li><li><strong>Arrêt brutal du serveur</strong> et fichiers de la base abîmés : PostgreSQL le dit dans son journal. Restaurez la dernière bonne sauvegarde : <code>sudo teuthis restaurer</code> (liste), puis <code>sudo teuthis restaurer &lt;nom&gt;</code>.</li><li><strong>Mémoire</strong> : <code>&quot;OOMKilled&quot;: true</code> (voir ci-dessus) ; relevez <code>TEUTHIS_MEMOIRE_POSTGRES</code> ou libérez de la mémoire.</li></ul><p>Ne supprimez jamais un volume (<code>docker volume rm</code>, <code>docker compose down -v</code>) pour « réparer » : <code>donnees-postgres</code> et <code>donnees-api</code> sont vos données.</p><h2 id="disque-plein" tabindex="-1">Disque plein <a class="header-anchor" href="#disque-plein" aria-label="Permalink to &quot;Disque plein {#disque-plein}&quot;">​</a></h2><p><code>df -h /opt/teuthis</code> (et <code>df -h /var/lib/docker</code> si Docker est ailleurs) dit où. Ce qui prend de la place, du plus fréquent au moins fréquent :</p><ul><li><strong>Les sauvegardes</strong> : <code>du -sh /opt/teuthis/sauvegardes/*</code>. Réduisez <code>TEUTHIS_SAUVEGARDE_CONSERVATION</code> dans le <code>.env</code> (7 par défaut) puis <code>docker compose up -d sauvegarde</code>, ou montez un autre disque et pointez <code>TEUTHIS_DOSSIER_SAUVEGARDES</code> dessus. Copiez d&#39;abord ce que vous voulez garder : ces copies sont les seules de l&#39;instance.</li><li><strong>Les anciennes images de Docker</strong> : <code>docker system df</code> mesure, <code>docker image prune</code> retire les images inutilisées (jamais celles d&#39;un service en cours).</li><li><strong>Les médias</strong> (volume <code>donnees-api</code>) : c&#39;est l&#39;usage normal, il faut un disque plus grand.</li></ul><p><code>sudo teuthis mettre-a-jour</code> refuse de démarrer s&#39;il manque la place de la sauvegarde ou des images.</p><h2 id="la-sauvegarde-est-unhealthy" tabindex="-1">La sauvegarde est unhealthy <a class="header-anchor" href="#la-sauvegarde-est-unhealthy" aria-label="Permalink to &quot;La sauvegarde est unhealthy {#la-sauvegarde-est-unhealthy}&quot;">​</a></h2><p>Le service <code>sauvegarde</code> passe en <code>unhealthy</code> si la dernière sauvegarde a échoué ou si aucune n&#39;a réussi depuis 26 heures. Le motif exact : <code>cat /opt/teuthis/sauvegardes/DERNIER-ECHEC.txt</code>, et <code>docker compose logs --tail 50 sauvegarde</code>. Causes fréquentes : <strong>la base n&#39;était pas joignable</strong> pendant la nuit (<a href="/teuthis-cms-distribution/documentation/referent/depannage#la-base-ne-démarre-pas">La base ne démarre pas</a>), <strong>le disque est plein</strong> (<a href="/teuthis-cms-distribution/documentation/referent/depannage#disque-plein">Disque plein</a>), un dossier de sauvegardes sur un disque monté qui a disparu. Un échec n&#39;efface jamais la dernière bonne copie. Une fois la cause corrigée, <code>sudo teuthis sauvegarder</code> fait une sauvegarde tout de suite ; si elle réussit, <code>DERNIER-ECHEC.txt</code> disparaît et le service redevient sain. Rappel : ces copies sont <strong>sur ce serveur</strong>.</p><h2 id="la-copie-distante-est-en-échec" tabindex="-1">La copie distante est en échec <a class="header-anchor" href="#la-copie-distante-est-en-échec" aria-label="Permalink to &quot;La copie distante est en échec {#la-copie-distante-est-en-échec}&quot;">​</a></h2><p><code>sudo teuthis copie-distante etat</code> dit depuis quand et pourquoi ; le motif exact est dans <code>sauvegardes/COPIE-DISTANTE-ECHEC.txt</code> (sa deuxième ligne donne le type : <em>copie</em>, <em>vérification</em> ou <em>configuration</em>), le détail dans <code>docker compose logs --tail 50 copie-distante</code>. Tant que le fichier existe, <code>copie-distante</code> et <code>sauvegarde</code> sont <code>unhealthy</code> ; il disparaît à la première copie réussie. Une tentative a lieu toutes les 30 minutes ; <code>sudo teuthis copie-distante essayer</code> en lance une tout de suite.</p><ul><li><strong>« la destination est injoignable »</strong> : le serveur ne joint pas l&#39;hébergeur (pare-feu sortant, panne, identifiants révoqués ou sans droit d&#39;écriture, compartiment supprimé). Les identifiants se changent en relançant <code>configurer</code> (le mot de passe du dépôt est conservé si vous le redonnez avec <code>--mot-de-passe-existant</code>).</li><li><strong>« le mot de passe du dépôt est refusé »</strong> : le dépôt de cette destination a un autre mot de passe que celui du serveur (destination partagée, ou fichier <code>copie-distante/mot-de-passe</code> remplacé). Redonnez le bon avec <code>configurer --mot-de-passe-existant</code>.</li><li><strong>« la vérification d&#39;intégrité du dépôt a échoué »</strong> : à prendre au sérieux — un objet du dépôt manque ou est altéré chez l&#39;hébergeur. Lancez <code>sudo teuthis copie-distante verifier</code> ; si l&#39;erreur persiste, commencez un dépôt neuf (autre préfixe) avec <code>configurer</code> : la prochaine copie le remplit.</li><li><strong>SFTP : « Connection reset » ou « Connection closed » juste après plusieurs essais de <code>configurer</code></strong> : depuis OpenSSH 9.8, un serveur SSH écarte quelques minutes une adresse qui multiplie les connexions sans s&#39;authentifier (relevés d&#39;empreinte). Attendez un quart d&#39;heure, puis relancez une seule fois, empreinte donnée (<code>--empreinte-hote</code>) : la commande ne relève alors les clés qu&#39;une fois.</li><li><strong>« délai dépassé »</strong> : la destination répond trop lentement (le délai d&#39;une copie est de 6 heures). Vérifiez le débit montant du serveur.</li><li>Les copies déjà envoyées ne sont jamais perdues par un échec : seule la dernière manque.</li></ul><h2 id="le-mot-de-passe-de-la-copie-est-perdu" tabindex="-1">Le mot de passe de la copie est perdu <a class="header-anchor" href="#le-mot-de-passe-de-la-copie-est-perdu" aria-label="Permalink to &quot;Le mot de passe de la copie est perdu {#le-mot-de-passe-de-la-copie-est-perdu}&quot;">​</a></h2><p><strong>La copie distante est alors irrécupérable.</strong> Aucun mécanisme de secours n&#39;existe, par construction : l&#39;hébergeur ne peut pas la lire, et nous non plus. Tant que le serveur vit, <code>/opt/teuthis/copie-distante/mot-de-passe</code> le contient (<code>sudo cat</code> — copiez-le tout de suite dans votre gestionnaire de mots de passe). Si le serveur est perdu <strong>et</strong> le mot de passe aussi, les copies chez l&#39;hébergeur ne servent plus à rien : supprimez-les. En attendant d&#39;avoir retrouvé le mot de passe, ne remplacez pas la configuration (l&#39;ancien est gardé dans <code>mot-de-passe.precedent</code>).</p><h2 id="lempreinte-de-lhôte-sftp-a-changé" tabindex="-1">L&#39;empreinte de l&#39;hôte SFTP a changé <a class="header-anchor" href="#lempreinte-de-lhôte-sftp-a-changé" aria-label="Permalink to &quot;L&#39;empreinte de l&#39;hôte SFTP a changé {#lempreinte-de-lhôte-sftp-a-changé}&quot;">​</a></h2><p>La copie échoue avec « l&#39;empreinte de l&#39;hôte SFTP n&#39;est pas celle enregistrée ». C&#39;est voulu : soit votre fournisseur a <strong>réinstallé</strong> son serveur (son annonce l&#39;indique), soit quelqu&#39;un s&#39;interpose. <strong>Ne contournez rien</strong> : demandez à votre fournisseur la nouvelle empreinte par un autre canal, puis relancez <code>sudo teuthis copie-distante configurer</code> avec <code>--empreinte-hote SHA256:…</code> (le dépôt existant se rouvre avec <code>--mot-de-passe-existant</code>).</p><h2 id="une-mise-à-jour-a-échoué" tabindex="-1">Une mise à jour a échoué <a class="header-anchor" href="#une-mise-à-jour-a-échoué" aria-label="Permalink to &quot;Une mise à jour a échoué {#une-mise-à-jour-a-échoué}&quot;">​</a></h2><p><code>sudo teuthis mettre-a-jour</code> dit toujours <strong>ce qui a échoué</strong>, <strong>où est le journal</strong> (<code>/opt/teuthis/journaux/mise-a-jour-*.log</code>) et <strong>dans quel état est l&#39;instance</strong>.</p><ul><li><strong>Refus avant toute modification</strong> (« Rien n&#39;a été modifié ») : pile qui n&#39;est pas saine (réglez-la d&#39;abord : <code>sudo teuthis diagnostic</code>), disque insuffisant, somme de l&#39;archive qui ne correspond pas, version absente du dépôt de distribution, variable obligatoire manquante dans le <code>.env</code> (le message la nomme : ajoutez-la, relancez), signature ou empreinte d&#39;image refusée (<strong>ne contournez pas ce refus</strong> : signalez-le), « refus de descendre de version ».</li><li><strong>Échec après la sauvegarde</strong> : le message se termine par <strong>« Retour arrière réussi : l&#39;instance est revenue à la version X »</strong>. La base et les fichiers sont ceux de la sauvegarde prise juste avant ; l&#39;instance fonctionne comme avant la tentative. Lisez le journal pour la cause (service qui n&#39;est pas devenu sain, <code>/api/sante</code> en erreur…), corrigez-la ou attendez une version corrigée, puis relancez. Le diagnostic (<code>sudo teuthis diagnostic</code>) garde la fin du dernier journal de mise à jour.</li><li><strong>« Le retour arrière n&#39;a PAS abouti »</strong> (code de sortie 2) : l&#39;instance n&#39;est probablement pas en service, mais <strong>la sauvegarde est intacte</strong>. Remettez-la : <code>sudo teuthis restaurer &lt;nom indiqué&gt; --avec-pile</code>, puis <code>sudo teuthis etat</code>.</li><li><strong>« Une autre commande teuthis modifie déjà cette instance »</strong> : une mise à jour (ou une restauration) est en cours. Attendez. S&#39;il n&#39;y en a aucune (processus tué net), supprimez le verrou : <code>sudo rm -rf /opt/teuthis/.verrou-teuthis</code>.</li><li><strong>Interrompue avec <code>Ctrl-C</code></strong> : le même retour arrière automatique s&#39;applique si la sauvegarde était faite.</li></ul><h2 id="les-courriels-ne-partent-pas" tabindex="-1">Les courriels ne partent pas <a class="header-anchor" href="#les-courriels-ne-partent-pas" aria-label="Permalink to &quot;Les courriels ne partent pas {#les-courriels-ne-partent-pas}&quot;">​</a></h2><p>Sans relais, <strong>aucun courriel ne part, par construction</strong> : les demandes déposées restent enregistrées et visibles au guichet du back-office (notice, §6.1). Vérifiez ce qui est réglé, sans afficher de mot de passe : <code>grep -E &#39;^(SMTP_HOST|SMTP_PORT|SMTP_SECURITY|MAIL_FROM)=&#39; /opt/teuthis/.env</code>. <code>SMTP_HOST</code> ou <code>MAIL_FROM</code> vide : renseignez-les.</p><p>Quand un relais <strong>est</strong> configuré mais <strong>injoignable ou refusé</strong>, l&#39;API ne fait pas semblant : elle répond <strong>503</strong> en nommant le relais (c&#39;est le comportement des modules livrés inactifs, <a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a>) et le journal des envois marque le message non délivré. Cherchez dans <code>docker compose logs --tail 100 cms-api | grep -i smtp</code>. Causes fréquentes : un port sortant bloqué par l&#39;hébergeur (le 25 l&#39;est presque toujours : utilisez 587 ou 465), <code>SMTP_SECURITY</code> qui ne correspond pas au port (<code>starttls</code> pour 587, <code>ssl</code> pour 465), un identifiant ou un mot de passe refusés. Après avoir corrigé le <code>.env</code> : <code>docker compose up -d cms-api cms-scheduler</code>.</p><h2 id="le-captcha-refuse-tout" tabindex="-1">Le captcha refuse tout <a class="header-anchor" href="#le-captcha-refuse-tout" aria-label="Permalink to &quot;Le captcha refuse tout {#le-captcha-refuse-tout}&quot;">​</a></h2><p><strong>Aucun formulaire public n&#39;accepte de soumission tant que <code>CAPTCHA_PROVIDER</code> et <code>CAPTCHA_SECRET_KEY</code> ne sont pas réglés</strong> (notice, §6.2) : c&#39;est voulu, l&#39;API répond en nommant le réglage manquant et le formulaire affiche « momentanément indisponible ». L&#39;installateur les pose (<code>altcha</code>, clé générée) ; une instance montée à la main ou un <code>.env</code> modifié peut les avoir perdus. <code>grep -E &#39;^CAPTCHA_(PROVIDER|SITE_KEY)=&#39; /opt/teuthis/.env</code> (la clé secrète ne s&#39;affiche pas ici), puis <code>docker compose up -d cms-api cms-scheduler</code>. Avec <code>turnstile</code> ou <code>hcaptcha</code>, le serveur doit pouvoir joindre le fournisseur, et la clé publique (<code>CAPTCHA_SITE_KEY</code>) doit être celle du bon site. Si le réglage est bon et que tout est quand même refusé, <strong>vérifiez l&#39;horloge</strong> (ci-dessous) : les énigmes d&#39;<code>altcha</code> sont datées.</p><h2 id="lhorloge-du-serveur" tabindex="-1">L&#39;horloge du serveur <a class="header-anchor" href="#lhorloge-du-serveur" aria-label="Permalink to &quot;L&#39;horloge du serveur {#lhorloge-du-serveur}&quot;">​</a></h2><p>Une horloge qui dérive casse en silence : certificats « pas encore valides » ou « expirés » dans les navigateurs, refus d&#39;émission par Let&#39;s Encrypt, énigmes de captcha périmées, sessions qui expirent aussitôt, sauvegarde nocturne à une heure inattendue. <code>date -u</code> et <code>timedatectl</code> donnent l&#39;heure et l&#39;état de la synchronisation (<code>System clock synchronized: yes</code>). Activez-la : <code>sudo timedatectl set-ntp true</code> (sur Debian, au besoin <code>sudo apt-get install systemd-timesyncd</code>). Les conteneurs suivent l&#39;horloge du serveur ; le fuseau de la sauvegarde se règle par <code>TEUTHIS_FUSEAU</code> (Europe/Paris par défaut). Le diagnostic imprime l&#39;heure UTC et locale du serveur.</p>',41)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
